import json, pathlib
P = pathlib.Path(__file__).resolve().parent.parent / 'refs' / 'rules_v2.json'
J = json.loads(P.read_text(encoding='utf-8'))
R = {r['c']: r for r in J['RULES']}
S = {s['id']: s for s in J['sources']}

def src(id, **kw):
    if id in S: S[id].update(kw)
    else:
        kw['id'] = id; J['sources'].append(kw); S[id] = kw

def up(c, drop_verify=False, **kw):
    r = R[c]; r.update(kw)
    if drop_verify: r.pop('verify', None)
    r['status'] = 'checked-1009'

